// Node: Code chuẩn hóa 3 Options (Tương thích OpenAI gpt-4o-mini, Gemini, Groq & Claude)
const items = $input.all();

// ---- Helper: cố gắng parse 1 string thành JSON, có dọn code-fence ----
function tryParseJSON(str) {
  if (typeof str !== 'string') return null;
  const cleaned = str
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    return null;
  }
}

// ---- Helper: dò đệ quy trong mọi cấu trúc (object/array/string-JSON)
// để tìm object có chứa option_1 / option_2 / option_3 ----
function deepFindOptions(node, depth = 0) {
  if (!node || depth > 10) return null;

  // Nếu là string -> thử parse JSON rồi đệ quy tiếp
  if (typeof node === 'string') {
    const parsed = tryParseJSON(node);
    return parsed ? deepFindOptions(parsed, depth + 1) : null;
  }

  if (typeof node !== 'object') return null;

  // Tìm thấy đích rồi
  if (node.option_1 || node.option_2 || node.option_3) return node;

  // Ưu tiên các key "bọc" hay gặp ở các provider (OpenAI/Gemini/Groq/Claude)
  const priorityKeys = ['text', 'content', 'message', 'output', 'candidates', 'parts'];

  if (Array.isArray(node)) {
    for (const el of node) {
      const found = deepFindOptions(el, depth + 1);
      if (found) return found;
    }
    return null;
  }

  for (const key of priorityKeys) {
    if (key in node) {
      const found = deepFindOptions(node[key], depth + 1);
      if (found) return found;
    }
  }

  // Cuối cùng mới quét toàn bộ các key còn lại (phòng trường hợp lạ)
  for (const key of Object.keys(node)) {
    if (priorityKeys.includes(key)) continue;
    const found = deepFindOptions(node[key], depth + 1);
    if (found) return found;
  }

  return null;
}

return items.map((item, index) => {
  const j = item.json;

  // 1 & 2. TÌM parsed BẰNG DEEP SEARCH (thay cho việc đoán path cứng trước đây)
  const parsed = deepFindOptions(j) || {};

  // 3. LẤY ROW_NUMBER TỪ NODE LẶP CHUẨN XÁC THEO LUẬT LẶP
  let rowId = j.row_number || j.row_id || j.id || "";

  // Thử lấy từ Node Lặp (Loop Over Items2 / Loop Over Items)
  if (!rowId) {
    try {
      rowId = $('Loop Over Items2').itemMatching(index)?.json?.row_number || "";
    } catch (e) {}
  }
  if (!rowId) {
    try {
      rowId = $('Lặp từng bài đã có content').itemMatching(index)?.json?.row_number || "";
    } catch (e) {}
  }
  if (!rowId) {
    try {
      rowId = $('Xử lý gom các nội dung trùng').itemMatching(index)?.json?.row_number || "";
    } catch (e) {}
  }

  // 4. LẤY LINK THƯ MỤC ẢNH DEMO (NẾU CÓ)
  let folderLink = "";
  try {
    folderLink = $('Tách ảnh từ nhiều link').itemMatching(index)?.json?.drive_folder_link || "";
  } catch (e) {}
  if (!folderLink) {
    try {
      folderLink = $('Loop Over Items2').itemMatching(index)?.json?.["Kho Media Drive"] || "";
    } catch (e) {}
  }
  if (!folderLink) {
    try {
      folderLink = $('Xử lý gom các nội dung trùng').itemMatching(index)?.json?.["Kho Media Drive"] || "";
    } catch (e) {}
  }
  if (!folderLink) {
    folderLink = j["Kho Media Drive"] || j["Kho Media"] || j["Ảnh Demo"] || j.drive_folder_link || "";
  }

  // 5. BÓC TÁCH NỘI DUNG 3 OPTION & CHUẨN HÓA CÂU TỪ
  const op1 = parsed.option_1 || {};
  const op2 = parsed.option_2 || {};
  const op3 = parsed.option_3 || {};

  let hashtags = parsed.hashtags || "#GaAiCapVan #GaGiongSieuTrung #ChannuoiHieuQua #Ecolar";
  hashtags = String(hashtags)
    .replace(/NongNghiepEcolar/gi, "Ecolar")
    .replace(/NongNghiep/gi, "")
    .replace(/#+/g, "#")
    .trim();

  // KHỐI THÔNG TIN LIÊN HỆ CHÈN BỔ SUNG SAU HASHTAG
  const contactInfo = `-------------------------------------------
Ecolar – Lối sống xanh bền vững
🌐 Website: https://ecolar.vn/
📞Hotline: 0868 515 668
📧Email: lienhe@ecolar.vn
📘Zalo OA: https://zalo.me/1699772582506373938
 ⓕ Facebook: https://www.facebook.com/Loisongxanhecolar
▶️Youtube: https://www.youtube.com/@LoiSongXanhEcolar
🎵Tiktok: https://www.tiktok.com/@gaaicapecolar`;

  // Ghép Hashtags và Thông tin liên hệ
  const footer = `${hashtags}\n\n${contactInfo}`;

  // Hàm định dạng và dọn dẹp từng Option
  function cleanAndFormat(opObj) {
    if (!opObj || (typeof opObj === 'object' && Object.keys(opObj).length === 0)) return "";
    if (typeof opObj === 'string') {
      const p = tryParseJSON(opObj);
      if (p) opObj = p;
      else return opObj;
    }

    let hook = opObj.hook || "";
    let body = opObj.content || "";
    if (typeof body === 'object') body = JSON.stringify(body);

    // Gỡ các nhãn HOOK / NỘI DUNG thừa
    hook = String(hook).replace(/^📌?\s*HOOK\s*:\s*/gi, "").replace(/^\[.*?\]\s*/gim, "").trim();
    body = String(body).replace(/^📝?\s*NỘI DUNG\s*:\s*/gi, "").replace(/^\[.*?\]\s*/gim, "").trim();

    // Ghép Hook & Body
    let fullText = "";
    if (hook && !body.toLowerCase().includes(hook.toLowerCase())) {
      const hasEmoji = /^[\u{1F300}-\u{1F9FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/u.test(hook);
      const hookFormatted = hasEmoji ? hook : `📌 ${hook}`;
      fullText = `${hookFormatted}\n\n${body}`;
    } else {
      fullText = body;
    }

    // Dọn dẹp ký hiệu Markdown còn sót (in đậm/in nghiêng/heading/bullet)
    fullText = fullText
      .replace(/\*\*(.*?)\*\*/g, "$1")   // **bold** -> bold
      .replace(/__(.*?)__/g, "$1")        // __bold__ -> bold
      .replace(/(?<!\*)\*(?!\*)(.*?)\*(?!\*)/g, "$1") // *italic* -> italic
      .replace(/^#{1,6}\s*/gm, "")        // # Heading -> Heading
      .replace(/^[\*\-]\s+/gm, "• ");     // - item / * item -> • item

    // Dọn dẹp tên thương hiệu Ecolar chuẩn mực & gỡ nhãn AI
    fullText = fullText
      .replace(/\[\s*Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?\s*\]/gi, "")
      .replace(/\(\s*Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?\s*\)/gi, "")
      .replace(/Nội dung (do|được)?\s*AI\s*(tạo|sáng tạo|sinh)?/gi, "")
      .replace(/AI-generated\s*content/gi, "")
      .replace(/Nông\s+Nghiệp\s+Ecolar/gi, "Ecolar")
      .replace(/Nông\s+nghiệp\s+Ecolar/gi, "Ecolar")
      .replace(/nông\s+nghiệp\s+Ecolar/gi, "Ecolar")
      .replace(/Công\s+ty\s+Ecolar/gi, "Ecolar")
      .replace(/\n{3,}/g, "\n\n")
      .trim();

    return fullText;
  }

  const text1 = cleanAndFormat(op1);
  const text2 = cleanAndFormat(op2);
  const text3 = cleanAndFormat(op3);

  // 6. CHUẨN HÓA DỮ LIỆU ĐẦU RA CHO CỘT GOOGLE SHEETS
  return {
    json: {
      "row_number": rowId,
      "Option_1": text1 ? `${text1}\n\n${footer}`.trim() : "",
      "Option_2": text2 ? `${text2}\n\n${footer}`.trim() : "",
      "Option_3": text3 ? `${text3}\n\n${footer}`.trim() : "",
      "Anh_Demo": folderLink,
      "Trạng thái": "waiting_review"
    }
  };
});

const allItems = $input.all();

// 1. Danh sách các cột master cần kế thừa dữ liệu
const MASTER_FIELDS = [
  "Mục đích chính",
  "Thông tin thương hiệu/sản phẩm/dịch vụ/USP",
  "Chân dung & Insight khách hàng",
