// Bóc tách **từ khoá** thành text sạch + danh sách từ cần nhấn mạnh riêng
function stripBold(text) {
  return String(text || "").replace(/\*\*(.+?)\*\*/g, "$1");
}
function extractBoldWords(text) {
  const matches = [...String(text || "").matchAll(/\*\*(.+?)\*\*/g)];
  return matches.map(m => m[1]);
}

function describeOrientation(layoutNote) {
  const m = String(layoutNote || "").match(/(\d+)\s*x\s*(\d+)/i);
  if (!m) return "";
  const w = parseInt(m[1]), h = parseInt(m[2]);
  if (w === h) return "Ảnh VUÔNG (tỉ lệ 1:1)";
  if (w > h) return `Ảnh NGANG (tỉ lệ ${(w / h).toFixed(2)}:1)`;
  return `Ảnh DỌC (tỉ lệ 1:${(h / w).toFixed(2)})`;
}

function formatRichContent(contentType, richContent) {
  if (!richContent) return "";
  if (contentType === "tagline") {
    return stripBold(richContent.tagline_text || "");
  }
  if (contentType === "paragraph") {
    return stripBold(richContent.paragraph_text || "");
  }
  if (contentType === "list" && Array.isArray(richContent.list_items)) {
    return richContent.list_items.map(stripBold).join("\n- ");
  }
  if (contentType === "icon_grid" && Array.isArray(richContent.grid_items)) {
    return richContent.grid_items.map(item => `${item.icon || ''} ${stripBold(item.label || '')}`).join(" | ");
  }
  return typeof richContent === "object" ? JSON.stringify(richContent) : String(richContent);
}

function cleanLayoutNote(layoutNote, orientationLabel) {
  const text = String(layoutNote || "");
  const m = text.match(/\((\d+x\d+)px?\)\s*-\s*(.+)$/i);
  if (!m) return text;
  const dimension = m[1];
  const description = m[2].trim();
  return `${dimension}px${orientationLabel ? ` (${orientationLabel})` : ''} — Nội dung chính: ${description}`;
}

function collectEmphasisWords(contentType, richContent) {
  if (!richContent) return [];
  if (contentType === "tagline") return extractBoldWords(richContent.tagline_text);
  if (contentType === "paragraph") return extractBoldWords(richContent.paragraph_text);
  if (contentType === "list" && Array.isArray(richContent.list_items)) {
    return richContent.list_items.flatMap(extractBoldWords);
  }
  if (contentType === "icon_grid" && Array.isArray(richContent.grid_items)) {
    return richContent.grid_items.flatMap(item => extractBoldWords(item.label));
  }
  return [];
}

